    { title: "Mobile Commerce", href: "#mobile" },
    { title: "Platform Extensions", href: "#extensions" },
  ],
};

export const agentsConfig = {
  hero: {
    title: "Agentic commerce has arrived",
    subtitle: "Build unified agentic experiences that securely act on behalf of users by leveraging Universal Commerce Protocol (UCP) with CommerceForge MCP servers.",
    cta: { text: "Start building", href: "#" },
  },
  protocolOverview: {
    title: "Universal Commerce Protocol",
    description: "The Universal Commerce Protocol (UCP) is an open standard that establishes a common language and a set of primitives that allow agents, merchants, Payment Service Providers (PSPs), and Credential Providers (CPs) to communicate consistently and securely across the web. CommerceForge provides MCP tools that are UCP-compliant to build with this interoperable and extensible protocol.",
  },
  protocolActors: [
    { title: "Agent", description: "Platforms, agents, and applications acting on behalf of buyers" },
