    { title: "PSP", description: "Payment Service Providers handling payment processing" },
  ],
  howItWorks: [
    { title: "Discovery", description: "Search products across the platform, retrieve details, and help buyers find what they're looking for." },
    { title: "Checkout", description: "Create checkout sessions, collect buyer information, attach payment information, and direct buyers to finish purchases on merchant storefronts." },
  ],
  productDiscovery: {
    title: "Product Discovery",
    description: "Agents can query all merchants across the CommerceForge platform, apply relevant filters, and display results buyers can interact with using the Catalog MCP server. Once buyers select a product, agentic apps can retrieve variant details needed to create checkout sessions.",
  },
  checkoutFlow: {
    title: "Checkout Flow",
    description: "As buyers select items from the Catalog, agentic apps can create and update carts and checkouts. Apps can refer buyers directly to merchant storefronts to complete checkout. All developers with Catalog access can direct buyers through Checkout, building referral applications and advertising models by controlling marketing attribution on top of UCP.",
