  },
  sidebar: [
    { title: "Overview", href: "agents.html", active: true },
    { title: "Protocol Overview", href: "#protocol" },
    { title: "How It Works", href: "#how-it-works" },
    { title: "Product Discovery", href: "#discovery" },
    { title: "Checkout Flow", href: "#checkout" },
  ],
};

export const supportConfig = {
  hero: {
    title: "Get answers from Dev Community",
