  overflow-x: auto;
}

.code-block .comment {
  color: var(--text-tertiary);
}

.code-block .cmd {
  color: var(--accent-secondary);
}

.install-cmd {
  margin-bottom: 16px;
}

.steps {
  margin-top: 16px;
}

.steps ol {
  margin: 0;
  padding-left: 20px;
  color: var(--text-secondary);
  font-size: 14px;
}

.steps li {
