  margin-left: 12px;
}

.status-badge.coming-soon {
  background: rgba(0, 217, 255, 0.1);
  border-color: rgba(0, 217, 255, 0.3);
  color: var(--accent);
}

/* Protocol Diagram */
.protocol-actors {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin: 32px 0;
}

.actor-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 24px;
  text-align: center;
}

.actor-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--accent) 0%, rgba(0, 217, 255, 0.5) 100%);
  border-radius: 14px;
  color: var(--bg-primary);
}

.actor-card h4 {
  font-size: 17px;
  margin-bottom: 8px;
}

.actor-card p {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0;
}

/* Mobile Responsiveness */
@media (max-width: 1024px) {
  .docs-sidebar {
    position: fixed;
    left: 0;
    top: 64px;
    z-index: 40;
    transform: translateX(-100%);
  }

  .docs-sidebar.open {
    transform: translateX(0);
  }

  .docs-sidebar.collapsed {
    transform: translateX(-100%);
    width: 280px;
  }

  .sidebar-toggle {
    left: 16px;
  }

  .docs-content {
    padding: 32px 24px;
  }

  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .protocol-actors {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .hero h1 {
    font-size: 36px;
  }

  .hero p {
    font-size: 16px;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-header h2 {
    font-size: 28px;
  }

  .docs-hero h1 {
    font-size: 32px;
  }

  .grid-3,
  .grid-2 {
    grid-template-columns: 1fr;
  }

  .protocol-actors {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .hero {
    padding: 48px 16px;
  }

  .hero h1 {
    font-size: 28px;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .tabs {
    width: 100%;
    overflow-x: auto;
  }
}

